let dark=false;try{dark=localStorage.getItem('targiluchit-theme')==='dark'}catch{}function applyTheme(){document.body.classList.toggle('dark',dark);$('#theme').setAttribute('aria-label',dark?'מעבר לערכת צבעים בהירה':'מעבר לערכת צבעים כהה');$('#theme').textContent=dark?'☀':'◐'}$('#theme').onclick=()=>{dark=!dark;try{localStorage.setItem('targiluchit-theme',dark?'dark':'light')}catch{}applyTheme()};applyTheme();
function updateScore(){if(celebrating)return;let count=Object.keys(found).length;$('#found-count').textContent=count;$('#total').textContent=total===null?'…':total;let pct=total?Math.min(100,Math.round(count/total*100)):0;$('#bar').style.width=pct+'%';$('#percent').textContent=pct+'%';let list=$('#discoveries');list.innerHTML='';if(!count){let e=document.createElement('div');e.className='empty';e.textContent='התרגיל הראשון שלך מחכה להתגלות.';list.appendChild(e)}else Object.values(found).reverse().forEach(x=>{let row=document.createElement('div');row.className='discovery';row.textContent=x+' = '+target;list.appendChild(row)});renderLadder(count)}
function renderLadder(count){let ladder=$('#ladder');ladder.innerHTML='';if(!backendReady){let note=document.createElement('div');note.className='empty';note.textContent='טבלת הדירוג עדיין לא מחוברת.';ladder.appendChild(note);return}if(!leaderboard.length){let note=document.createElement('div');note.className='empty';note.textContent='עוד אין תוצאות להיום. אולי שלך תהיה הראשונה?';ladder.appendChild(note);return}leaderboard.forEach((x,i)=>{let row=document.createElement('div');row.className='ladder-row';let rank=document.createElement('span');rank.className='rank';rank.textContent=String(i+1).padStart(2,'0');let avatar=document.createElement('span');avatar.className='avatar';avatar.textContent=x.display_name[0];let detail=document.createElement('div'),name=document.createElement('strong'),sub=document.createElement('small');name.textContent=x.display_name;sub.textContent=x.is_me?'התוצאות שלי':'שחקן';detail.append(name,sub);let score=document.createElement('b');score.textContent=x.score;row.append(rank,avatar,detail,score);ladder.appendChild(row)})}
async function refreshLeaderboard(){if(!db)return;const {data,error}=await db.rpc('daily_leaderboard');if(error){console.error(error);toast('לא ניתן לטעון את הדירוג');return}leaderboard=data||[];renderLadder(Object.keys(found).length)}
async function loadSolutions(){if(!user)return;const {data,error}=await db.rpc('my_solutions');if(error){console.error(error);toast('לא ניתן לטעון את התרגילים השמורים');return}found=Object.fromEntries((data||[]).map(x=>[x.solution_key,x.expression]));migrateDiscoveries(false);updateScore()}
async function submitSolution(result){const {data,error}=await db.rpc('submit_solution',{tree:result.tree});if(error){console.error(error);delete found[result.key];updateScore();toast('השמירה נכשלה. נסו שוב');return}await loadSolutions();await refreshLeaderboard()}
async function initializeBackend(){const config=window.TARGILUCHIT_CONFIG;if(!config?.supabaseUrl||!config?.supabaseAnonKey||!window.supabase){$('#auth-status').textContent='משחק אורח · השמירה במכשיר הזה';return}try{db=window.supabase.createClient(config.supabaseUrl,config.supabaseAnonKey);const {data:puzzle,error}=await db.rpc('daily_riddle');if(error)throw error;if(puzzle.day!==dateKey){location.reload();return}digits=puzzle.digits;target=puzzle.target;storeKey='targiluchit-v2:'+dateKey;try{found=JSON.parse(localStorage.getItem(storeKey)||'{}')}catch{found={}}migrateDiscoveries();let ds=digits.join('');$('#plate-number').textContent=target>=100?`${ds.slice(0,3)}-${ds.slice(3)}-${target}`:`${ds.slice(0,2)}-${ds.slice(2)}-${target}`;$('#target').textContent=target;backendReady=true;reset(false);calculateTotal();let session=await db.auth.getSession();user=session.data.session?.user||null;await authChanged();db.auth.onAuthStateChange((_event,session)=>{user=session?.user||null;setTimeout(authChanged,0)});await refreshLeaderboard()}catch(error){console.error(error);db=null;backendReady=false;$('#auth-status').textContent='החיבור למשחק אינו זמין כרגע';toast('לא ניתן להתחבר לשרת')}}
async function authChanged(){$('#auth-button').textContent=user?'התנתקות':'כניסה עם Google';$('#auth-status').textContent=user?'מחוברים בתור '+(user.user_metadata?.full_name||'שחקן'):'כניסה לשמירת התוצאות והשתתפות בדירוג';if(user)await loadSolutions();else{try{found=JSON.parse(localStorage.getItem(storeKey)||'{}')}catch{found={}}migrateDiscoveries();updateScore()}await refreshLeaderboard()}
$('#auth-button').onclick=async()=>{if(!db){toast('הכניסה עדיין לא הוגדרה');return}if(user){const {error}=await db.auth.signOut();if(error)toast('לא ניתן להתנתק');return}const {error}=await db.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+location.pathname}});if(error)toast('לא ניתן להתחבר עם Google')};
function calculateTotal(){setTimeout(()=>{let dp=Array.from({length:32},()=>new Map());digits.forEach((d,i)=>dp[1<<i].set(String(d),leaf(d)));for(let mask=1;mask<32;mask++){if((mask&(mask-1))===0)continue;for(let a=(mask-1)&mask;a;a=(a-1)&mask){let b=mask^a;if(!b||a>b)continue;for(const x of dp[a].values())for(const y of dp[b].values()){for(const z of [concatenate(x,y),concatenate(y,x),combine(x,y,'+'),combine(x,y,'*'),combine(x,y,'-'),combine(y,x,'-'),combine(x,y,'//'),combine(y,x,'//')])if(z)dp[mask].set(z.key,z)}}}total=[...dp[31].values()].filter(x=>Math.abs(x.v-target)<1e-9).length;updateScore()},30)}
reset();calculateTotal();initializeBackend();

setInterval(()=>{const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jerusalem',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());if(today!==dateKey)location.reload()},60000);
